[
  {
    "scenarios": [
      "features/todos.feature:Existing todo element persists when marked completed",
      "features/todos.feature:Existing todo elements persist when marking all as completed",
      "features/todos.feature:Clearing the completed state preserves remaining elements",
      "features/todos.feature:Existing todo elements persist when creating a new todo"
    ]
  }
]

const fs = require('node:fs');
const path = require('node:path');
const { setWorldConstructor, Before, After } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');

const ROOT = path.resolve(__dirname, '..', '..');

class AppWorld {
  // Load the REAL page and the REAL app. A missing artifact is a loud failure here, not a
  // silently-green suite: the executable tier must exercise the production artifact.
  loadApp() {
    const indexPath = path.join(ROOT, 'index.html');
    const appPath = path.join(ROOT, 'js', 'app.js');
    if (!fs.existsSync(indexPath))
      throw new Error(`verification support: ${indexPath} does not exist — the app has no page to load`);
    if (!fs.existsSync(appPath))
      throw new Error(`verification support: ${appPath} does not exist — the app has no code to run`);
    const appSource = fs.readFileSync(appPath, 'utf8');
    if (appSource.trim().length === 0)
      throw new Error(`verification support: ${appPath} is empty — there is no application to verify`);

    // disableJavaScriptFileLoading: the harness executes app.js itself as inline source, and a
    // real <script src> under happy-dom attempts a network fetch (ECONNREFUSED, pilot 0.13.64).
    this.window = new Window({
      url: 'http://localhost/',
      settings: { disableJavaScriptFileLoading: true },
    });
    this.document = this.window.document;

    // The app must EXECUTE, not merely be present. Two things were measured 2026-07-28 and both
    // bit an earlier version of this harness:
    //   1. happy-dom does NOT run scripts the parser sees — neither an appended <script> with
    //      textContent nor one inlined into document.write(). window.eval() DOES run them. An
    //      earlier harness looked green while app.js never ran, because its only assertion
    //      checked that the PAGE had loaded. A weak test hid a broken loader.
    //   2. DOMContentLoaded never fires from write()/close(), so an app that defers its init to
    //      DOMContentLoaded or window.load — the common TodoMVC shape — would never initialise
    //      and the harness would fail CORRECT code. The lifecycle events are dispatched here.
    // disableJavaScriptFileLoading stops the page's own src tag attempting a network fetch
    // (ECONNREFUSED under happy-dom, pilot 0.13.64).
    this.document.write(fs.readFileSync(indexPath, 'utf8'));
    this.document.close();
    this.window.eval(appSource);
    this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
    this.window.dispatchEvent(new this.window.Event('load'));

    // ROUTING. happy-dom updates location.hash but NEVER fires hashchange — measured
    // 2026-07-28, both by assignment and by clicking an in-page anchor. A TodoMVC router
    // listens for hashchange, so without this the filter/back-button behaviour is
    // UNREACHABLE in this tier: one wave spent seven correction voyages implementing filter
    // links that nothing could ever drive, stuck at 22/29 the whole way. Route the two ways a
    // real browser changes the hash, so routing is exercisable rather than merely present.
    const w = this.window;
    this.document.addEventListener('click', (e) => {
      const a = e.target && e.target.closest ? e.target.closest('a[href^="#"]') : null;
      if (!a) return;
      const next = a.getAttribute('href');
      if (w.location.hash !== next) { w.location.hash = next; w.dispatchEvent(new w.Event('hashchange')); }
    }, true);
    return this.document;
  }

  // Drive the router the way a user's address bar does.
  navigate(hash) {
    if (!this.window) throw new Error('verification support: navigate() before the app was loaded');
    if (this.window.location.hash === hash) return;
    this.window.location.hash = hash;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  get localStorage() { return this.window.localStorage; }

  // A happy-dom Window holds timers, observers and native buffers; an undisposed one per
  // scenario grows without bound. Measured 2026-07-28: a wave whose own world.js never
  // disposed reached 13.6G RSS across ~45 scenarios and was OOM-killed by the kernel, which
  // ended the suite with a bare "Killed" and no summary line. NODE_OPTIONS
  // --max-old-space-size does NOT prevent this: the growth is outside V8's old space, so the
  // cap bounds the JS heap while the process still takes the box down. Disposal is the fix.
  async disposeApp() {
    const w = this.window;
    if (!w) return;
    this.window = undefined;
    this.document = undefined;
    if (w.happyDOM && typeof w.happyDOM.close === 'function') { await w.happyDOM.close(); return; }
    if (w.happyDOM && typeof w.happyDOM.abort === 'function') { await w.happyDOM.abort(); return; }
    if (typeof w.close === 'function') w.close();
  }
}

setWorldConstructor(AppWorld);

// Every scenario gets the real app. No scenario can pass without one.
Before(function () { this.loadApp(); });
// ...and every scenario gives it back.
After(async function () { await this.disposeApp(); });

const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('node:assert');
const path = require('node:path');
const fs = require('node:fs');

const ROOT = path.resolve(__dirname, '..', '..');

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function qs(sel) { return this.document.querySelector(sel); }
function qsa(sel) { return this.document.querySelectorAll(sel); }

function visible(el) {
  if (!el) return false;
  if (el.style && el.style.display === 'none') return false;
  if (el.classList && el.classList.contains('hidden')) return false;
  const style = el.ownerDocument.defaultView.getComputedStyle(el);
  if (style.display === 'none' || style.visibility === 'hidden') return false;
  const rect = el.getBoundingClientRect();
  if (rect.width === 0 && rect.height === 0) return false;
  return true;
}

// Find a todo <li> whose label text matches exactly.
function findTodoItem(container, text) {
  const items = container.querySelectorAll('.todo-list li');
  for (let i = 0; i < items.length; i++) {
    const label = items[i].querySelector('.view label');
    if (label && label.textContent.trim() === text) return items[i];
  }
  return null;
}

function todoItems() {
  return this.document.querySelectorAll('.todo-list li');
}

function todoTexts() {
  return Array.from(todoItems.call(this)).map(li =>
    li.querySelector('.view label').textContent.trim()
  );
}

// ---------------------------------------------------------------------------
// Background
// ---------------------------------------------------------------------------

Given('the app is loaded', function () {
  // The Before hook in world.js already loads the app into this.window / this.document.
  // This step confirms the page rendered.
  const h1 = qs.call(this, 'h1');
  assert.ok(h1, 'expected app to have an <h1>');
});

// ---------------------------------------------------------------------------
// Visual state – visibility assertions
// ---------------------------------------------------------------------------

Then('{string} should not be visible', function (sel) {
  const el = qs.call(this, sel);
  assert.ok(!el || !visible.call(this, el),
    `expected element ${sel} to not be visible`);
});

// ---------------------------------------------------------------------------
// Creating todos
// ---------------------------------------------------------------------------

When('I type {string} into the new todo input and press Enter', function (text) {
  const input = qs.call(this, '.new-todo');
  assert.ok(input, 'expected .new-todo input to exist');
  input.value = text;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', {
    key: 'Enter', keyCode: 13, which: 13, bubbles: true
  }));
});

Then('I should see {string} in the todo list', function (text) {
  const texts = todoTexts.call(this);
  assert.ok(texts.includes(text),
    `expected "${text}" in todo list, got [${texts.join(', ')}]`);
});

Then('the new todo input should be cleared', function () {
  const input = qs.call(this, '.new-todo');
  assert.ok(input, 'expected .new-todo input');
  assert.strictEqual(input.value, '', `expected input to be cleared, got "${input.value}"`);
});

Then('the todo list should remain empty', function () {
  const items = todoItems.call(this);
  assert.strictEqual(items.length, 0, `expected empty todo list, got ${items.length} items`);
});

// ---------------------------------------------------------------------------
// Toggling completion
// ---------------------------------------------------------------------------

Given('a todo {string} exists', function (text) {
  const input = qs.call(this, '.new-todo');
  assert.ok(input, 'expected .new-todo input');
  input.value = text;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', {
    key: 'Enter', keyCode: 13, which: 13, bubbles: true
  }));
});

Given('todos {string} and {string} exist', function (text1, text2) {
  const input = qs.call(this, '.new-todo');
  assert.ok(input, 'expected .new-todo input');
  input.value = text1;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', {
    key: 'Enter', keyCode: 13, which: 13, bubbles: true
  }));
  input.value = text2;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', {
    key: 'Enter', keyCode: 13, which: 13, bubbles: true
  }));
});

When('I click the toggle for {string}', function (text) {
  const li = findTodoItem(this.document, text);
  assert.ok(li, `expected todo "${text}" to exist`);
  const cb = li.querySelector('.toggle');
  assert.ok(cb, `expected toggle for "${text}"`);
  cb.click();
});

Then('{string} should be marked as completed', function (text) {
  const li = findTodoItem(this.document, text);
  assert.ok(li, `expected todo "${text}" to exist`);
  assert.ok(li.classList.contains('completed'),
    `expected "${text}" to have class "completed"`);
});

When('I click the {string} toggle', function (label) {
  // "Mark all as complete" toggle
  const toggle = qs.call(this, '#toggle-all');
  assert.ok(toggle, 'expected #toggle-all');
  toggle.click();
});

Then('all todos should be marked as completed', function () {
  const items = todoItems.call(this);
  assert.ok(items.length > 0, 'expected at least one todo');
  for (let i = 0; i < items.length; i++) {
    assert.ok(items[i].classList.contains('completed'),
      `expected todo ${i} to be completed`);
  }
});

When('I mark {string} as completed', function (text) {
  const li = findTodoItem(this.document, text);
  assert.ok(li, `expected todo "${text}"`);
  const cb = li.querySelector('.toggle');
  assert.ok(cb, `expected toggle for "${text}"`);
  // Only toggle if not already completed
  if (!li.classList.contains('completed')) {
    cb.click();
  }
});

Then('the {string} checkbox should be checked', function (label) {
  const toggle = qs.call(this, '#toggle-all');
  assert.ok(toggle, 'expected #toggle-all');
  assert.ok(toggle.checked,
    'expected #toggle-all to be checked');
});

// ---------------------------------------------------------------------------
// Editing todos
// ---------------------------------------------------------------------------

When('I double-click {string}', function (text) {
  const li = findTodoItem(this.document, text);
  assert.ok(li, `expected todo "${text}"`);
  const label = li.querySelector('.view label');
  assert.ok(label, `expected label for "${text}"`);
  label.dispatchEvent(new this.window.MouseEvent('dblclick', {
    bubbles: true, cancelable: true
  }));
});

Then('the todo should be in editing mode', function () {
  const editing = qs.call(this, '.todo-list li.editing');
  assert.ok(editing, 'expected a todo in editing mode');
});

When('I change the value to {string} and press Enter', function (text) {
  const li = qs.call(this, '.todo-list li.editing');
  assert.ok(li, 'expected a todo in editing mode');
  const edit = li.querySelector('.edit');
  assert.ok(edit, 'expected .edit input');
  edit.value = text;
  edit.dispatchEvent(new this.window.KeyboardEvent('keydown', {
    key: 'Enter', keyCode: 13, which: 13, bubbles: true
  }));
});

When('I change the value to {string} and blur the input', function (text) {
  const li = qs.call(this, '.todo-list li.editing');
  assert.ok(li, 'expected a todo in editing mode');
  const edit = li.querySelector('.edit');
  assert.ok(edit, 'expected .edit input');
  edit.value = text;
  edit.dispatchEvent(new this.window.FocusEvent('blur', { bubbles: true }));
});

When('I change the value to {string} and press Escape', function (text) {
  const li = qs.call(this, '.todo-list li.editing');
  assert.ok(li, 'expected a todo in editing mode');
  const edit = li.querySelector('.edit');
  assert.ok(edit, 'expected .edit input');
  edit.value = text;
  edit.dispatchEvent(new this.window.KeyboardEvent('keydown', {
    key: 'Escape', keyCode: 27, which: 27, bubbles: true
  }));
});

When('I clear the edit input and press Enter', function () {
  const li = qs.call(this, '.todo-list li.editing');
  assert.ok(li, 'expected a todo in editing mode');
  const edit = li.querySelector('.edit');
  assert.ok(edit, 'expected .edit input');
  edit.value = '';
  edit.dispatchEvent(new this.window.KeyboardEvent('keydown', {
    key: 'Enter', keyCode: 13, which: 13, bubbles: true
  }));
});

Then('the todo list should be empty', function () {
  const items = todoItems.call(this);
  assert.strictEqual(items.length, 0, `expected empty todo list, got ${items.length}`);
});

// ---------------------------------------------------------------------------
// Counter
// ---------------------------------------------------------------------------

Given('{string} is marked as completed', function (text) {
  const li = findTodoItem(this.document, text);
  assert.ok(li, `expected todo "${text}"`);
  const cb = li.querySelector('.toggle');
  assert.ok(cb, `expected toggle for "${text}"`);
  if (!li.classList.contains('completed')) {
    cb.click();
  }
});

Then('the todo count should show {string}', function (expected) {
  const count = qs.call(this, '.todo-count');
  assert.ok(count, 'expected .todo-count');
  const text = count.textContent.trim().replace(/\s+/g, ' ');
  assert.strictEqual(text, expected,
    `expected todo count "${expected}", got "${text}"`);
});

When('I create a todo {string}', function (text) {
  const input = qs.call(this, '.new-todo');
  assert.ok(input, 'expected .new-todo input');
  input.value = text;
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', {
    key: 'Enter', keyCode: 13, which: 13, bubbles: true
  }));
});

// ---------------------------------------------------------------------------
// Clear completed
// ---------------------------------------------------------------------------

When('I click {string}', function (text) {
  // Matches "Clear completed" button click
  const btn = qs.call(this, '.clear-completed');
  assert.ok(btn, 'expected .clear-completed button');
  btn.click();
});

Then('{string} should not appear in the todo list', function (text) {
  const texts = todoTexts.call(this);
  assert.ok(!texts.includes(text),
    `expected "${text}" to NOT be in todo list, but it was`);
});

Then('{string} should appear in the todo list', function (text) {
  const texts = todoTexts.call(this);
  assert.ok(texts.includes(text),
    `expected "${text}" in todo list, got [${texts.join(', ')}]`);
});

Then('the {string} button should not be visible', function (label) {
  const btn = qs.call(this, '.clear-completed');
  assert.ok(btn, 'expected .clear-completed button');
  assert.ok(!visible.call(this, btn),
    'expected clear-completed button to not be visible');
});

// ---------------------------------------------------------------------------
// Routing and filtering
// ---------------------------------------------------------------------------

Then('I should see {int} todos', function (n) {
  const items = todoItems.call(this);
  assert.strictEqual(items.length, n,
    `expected ${n} todos, got ${items.length}`);
});

Then('I should see {int} todo', function (n) {
  const items = todoItems.call(this);
  assert.strictEqual(items.length, n,
    `expected ${n} todo, got ${items.length}`);
});

When('I click the {string} filter', function (name) {
  const filters = qsa.call(this, '.filters a');
  let found = null;
  for (let i = 0; i < filters.length; i++) {
    if (filters[i].textContent.trim().toLowerCase() === name.toLowerCase()) {
      found = filters[i];
      break;
    }
  }
  assert.ok(found, `expected filter "${name}"`);
  found.click();
});

Then('it should be {string}', function (text) {
  const texts = todoTexts.call(this);
  assert.strictEqual(texts.length, 1, 'expected exactly one todo');
  assert.strictEqual(texts[0], text,
    `expected todo to be "${text}", got "${texts[0]}"`);
});

Then('the {string} filter link should have class {string}', function (name, cls) {
  const filters = qsa.call(this, '.filters a');
  let found = null;
  for (let i = 0; i < filters.length; i++) {
    if (filters[i].textContent.trim().toLowerCase() === name.toLowerCase()) {
      found = filters[i];
      break;
    }
  }
  assert.ok(found, `expected filter "${name}"`);
  assert.ok(found.classList.contains(cls),
    `expected filter "${name}" to have class "${cls}"`);
});

Then('the {string} filter link should not have class {string}', function (name, cls) {
  const filters = qsa.call(this, '.filters a');
  let found = null;
  for (let i = 0; i < filters.length; i++) {
    if (filters[i].textContent.trim().toLowerCase() === name.toLowerCase()) {
      found = filters[i];
      break;
    }
  }
  assert.ok(found, `expected filter "${name}"`);
  assert.ok(!found.classList.contains(cls),
    `expected filter "${name}" to NOT have class "${cls}"`);
});

Then('I should see only active todos', function () {
  const items = todoItems.call(this);
  for (let i = 0; i < items.length; i++) {
    assert.ok(!items[i].classList.contains('completed'),
      `expected no completed todos, but todo ${i} has "completed"`);
  }
});

// ---------------------------------------------------------------------------
// Persistence
// ---------------------------------------------------------------------------

When('I reload the app', function () {
  // Save raw localStorage data before dispose
  const ls = this.localStorage;
  const savedData = {};
  for (var i = 0; i < ls.length; i++) {
    var k = ls.key(i);
    savedData[k] = ls.getItem(k);
  }
  return this.disposeApp().then(() => {
    // Create fresh window manually, so we can pre-populate localStorage
    // before the app evaluates and reads its persisted state.
    var HappyWindow = require('happy-dom').Window;
    this.window = new HappyWindow({
      url: 'http://localhost/',
      settings: { disableJavaScriptFileLoading: true },
    });
    this.document = this.window.document;

    // Pre-set localStorage before app runs
    for (var k in savedData) {
      if (savedData.hasOwnProperty(k)) {
        this.localStorage.setItem(k, savedData[k]);
      }
    }

    // Write HTML and evaluate app
    var html = fs.readFileSync(path.resolve(ROOT, 'index.html'), 'utf8');
    var appSrc = fs.readFileSync(path.resolve(ROOT, 'js', 'app.js'), 'utf8');
    this.document.write(html);
    this.document.close();
    this.window.eval(appSrc);
    this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
    this.window.dispatchEvent(new this.window.Event('load'));

    // Re-register click-to-hashchange handler (same as world.js does)
    var w = this.window;
    this.document.addEventListener('click', function (e) {
      var a = e.target && e.target.closest ? e.target.closest('a[href^="#"]') : null;
      if (!a) return;
      var next = a.getAttribute('href');
      if (w.location.hash !== next) { w.location.hash = next; w.dispatchEvent(new w.Event('hashchange')); }
    }, true);
  });
});

// ---------------------------------------------------------------------------
// Schema conformance
// ---------------------------------------------------------------------------

Then('the localStorage todo items conform to the {string} schema in {string}', function (schemaId, schemaPath) {
  const schemaFile = path.resolve(ROOT, schemaPath);
  assert.ok(fs.existsSync(schemaFile), `schema file not found: ${schemaPath}`);
  const schema = JSON.parse(fs.readFileSync(schemaFile, 'utf8'));

  // Read todos from localStorage. TodoMVC typically stores under 'todos-*' key.
  // Find the key that starts with 'todos-'
  const ls = this.localStorage;
  let todosKey = null;
  for (let i = 0; i < ls.length; i++) {
    const k = ls.key(i);
    if (k && k.startsWith('todos-')) { todosKey = k; break; }
  }
  assert.ok(todosKey, 'expected a todos localStorage key (todos-*)');

  const raw = ls.getItem(todosKey);
  assert.ok(raw, `expected localStorage item "${todosKey}" to have a value`);
  let todos;
  try { todos = JSON.parse(raw); } catch (e) { assert.fail(`localStorage value is not valid JSON: ${e.message}`); }
  assert.ok(Array.isArray(todos), 'expected todos to be an array');

  // Validate each todo item against the schema
  for (let i = 0; i < todos.length; i++) {
    const item = todos[i];
    // Check required fields
    assert.ok(typeof item.id === 'string', `todo[${i}].id should be a string, got ${typeof item.id}`);
    assert.ok(typeof item.title === 'string', `todo[${i}].title should be a string, got ${typeof item.title}`);
    assert.ok(typeof item.completed === 'boolean', `todo[${i}].completed should be a boolean, got ${typeof item.completed}`);
    // Check no extra properties
    const allowed = ['id', 'title', 'completed'];
    const keys = Object.keys(item);
    for (const k of keys) {
      assert.ok(allowed.includes(k), `todo[${i}] has unexpected property "${k}"`);
    }
  }
});

(function () {
  'use strict';

  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;
  var STORAGE_KEY = 'todos-todomvc-shakedown';

  // -----------------------------------------------------------------------
  // Model
  // -----------------------------------------------------------------------

  function TodoStore() {
    this.todos = this.load();
  }

  /**
   * @planks("I reload the app")
   */
  TodoStore.prototype.load = function () {
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      return raw ? JSON.parse(raw) : [];
    } catch (e) {
      return [];
    }
  };

  /**
   * @planks("I reload the app")
   */
  TodoStore.prototype.save = function () {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(this.todos));
  };

  TodoStore.prototype.nextId = function () {
    return Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
  };

  /**
   * @planks("a todo {string} exists")
   * @planks("todos {string} and {string} exist")
   * @planks("I create a todo {string}")
   * @planks("I type {string} into the new todo input and press Enter")
   */
  TodoStore.prototype.add = function (title) {
    var todo = {
      id: this.nextId(),
      title: title,
      completed: false
    };
    this.todos.push(todo);
    this.save();
    return todo;
  };

  /**
   * @planks("I clear the edit input and press Enter")
   */
  TodoStore.prototype.remove = function (id) {
    this.todos = this.todos.filter(function (t) { return t.id !== id; });
    this.save();
  };

  /**
   * @planks("I change the value to {string} and press Enter")
   * @planks("I change the value to {string} and blur the input")
   */
  TodoStore.prototype.update = function (id, props) {
    for (var i = 0; i < this.todos.length; i++) {
      if (this.todos[i].id === id) {
        for (var k in props) {
          if (props.hasOwnProperty(k)) {
            this.todos[i][k] = props[k];
          }
        }
        this.save();
        return;
      }
    }
  };

  /**
   * @planks("I click the toggle for {string}")
   * @planks("I mark {string} as completed")
   * @planks("{string} is marked as completed")
   */
  TodoStore.prototype.toggle = function (id) {
    this.update(id, { completed: !this.get(id).completed });
  };

  TodoStore.prototype.get = function (id) {
    for (var i = 0; i < this.todos.length; i++) {
      if (this.todos[i].id === id) return this.todos[i];
    }
    return null;
  };

  TodoStore.prototype.active = function () {
    return this.todos.filter(function (t) { return !t.completed; });
  };

  TodoStore.prototype.completed = function () {
    return this.todos.filter(function (t) { return t.completed; });
  };

  /**
   * @planks("I click the {string} toggle")
   */
  TodoStore.prototype.toggleAll = function (checked) {
    for (var i = 0; i < this.todos.length; i++) {
      this.todos[i].completed = checked;
    }
    this.save();
  };

  /**
   * @planks("I click {string}")
   */
  TodoStore.prototype.clearCompleted = function () {
    this.todos = this.active();
    this.save();
  };

  // -----------------------------------------------------------------------
  // View / Controller
  // -----------------------------------------------------------------------

  var store = new TodoStore();
  var currentFilter = 'all';

  var todoapp = document.querySelector('.todoapp');
  var main = document.querySelector('.main');
  var footer = document.querySelector('.footer');
  var newTodo = document.querySelector('.new-todo');
  var todoList = document.querySelector('.todo-list');
  var toggleAll = document.querySelector('#toggle-all');
  var todoCount = document.querySelector('.todo-count');
  var clearCompleted = document.querySelector('.clear-completed');
  var filters = document.querySelectorAll('.filters a');

  function pluralize(count, word) {
    return count === 1 ? word : word + 's';
  }

  function getFilter() {
    var hash = location.hash.replace(/^#\/?/, '') || 'all';
    return hash === '' ? 'all' : hash;
  }

  function filterTodos(todos, filter) {
    if (filter === 'active') return store.active();
    if (filter === 'completed') return store.completed();
    return todos;
  }

  function bindFilterNav() {
    for (var i = 0; i < filters.length; i++) {
      filters[i].addEventListener('click', function (e) {
        e.preventDefault();
        var href = this.getAttribute('href');
        if (location.hash !== href) {
          location.hash = href;
        }
      });
    }
  }

  function updateFilterUI(filter) {
    for (var i = 0; i < filters.length; i++) {
      var a = filters[i];
      var href = a.getAttribute('href').replace('#/', '') || 'all';
      if (href === filter) {
        a.classList.add('selected');
      } else {
        a.classList.remove('selected');
      }
    }
  }

  /**
   * @planks("{string} should not be visible")
   * @planks("I should see {int} todos")
   * @planks("I should see {int} todo")
   * @planks("it should be {string}")
   * @planks("the {string} button should not be visible")
   * @planks("the {string} filter link should have class {string}")
   * @planks("the {string} filter link should not have class {string}")
   * @planks("I click the {string} filter")
   * @planks("I should see {string} in the todo list")
   * @planks("the todo count should show {string}")
   * @planks("I should see only active todos")
   * @planks("the {string} checkbox should be checked")
   * @planks("all todos should be marked as completed")
   * @planks("{string} should be marked as completed")
   * @planks("{string} should appear in the todo list")
   * @planks("{string} should not appear in the todo list")
   * @planks("the new todo input should be cleared")
   * @planks("the todo list should remain empty")
   * @planks("the todo list should be empty")
   * @planks("the todo should be in editing mode")
   */
  function render() {
    var filter = getFilter();
    currentFilter = filter;
    updateFilterUI(filter);

    var items = filterTodos(store.todos, filter);
    var activeCount = store.active().length;

    // Build list HTML
    var html = '';
    for (var i = 0; i < items.length; i++) {
      var todo = items[i];
      var liClass = '';
      if (todo.completed) liClass += 'completed';
      html += '<li' + (liClass ? ' class="' + liClass + '"' : '') + ' data-id="' + todo.id + '">';
      html += '<div class="view">';
      html += '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>';
      html += '<label>' + escapeHtml(todo.title) + '</label>';
      html += '<button class="destroy"></button>';
      html += '</div>';
      html += '<input class="edit" value="' + escapeHtml(todo.title) + '">';
      html += '</li>';
    }
    todoList.innerHTML = html;

    // Toggle all
    toggleAll.checked = store.todos.length > 0 && activeCount === 0;

    // Main and footer visibility
    var hasTodos = store.todos.length > 0;
    main.style.display = hasTodos ? 'block' : 'none';
    footer.style.display = hasTodos ? 'block' : 'none';

    // Count
    todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + pluralize(activeCount, 'item') + ' left';

    // Clear completed visibility
    var completedCount = store.completed().length;
    clearCompleted.style.display = completedCount > 0 ? 'block' : 'none';

    // Wire up events on rendered items
    bindItemEvents();
  }

  function escapeHtml(str) {
    var div = document.createElement('div');
    div.appendChild(document.createTextNode(str));
    return div.innerHTML;
  }

  // -----------------------------------------------------------------------
  // Item-level events (re-bound after each render)
  // -----------------------------------------------------------------------

  /**
   * @planks("I double-click {string}")
   * @planks("I change the value to {string} and press Enter")
   * @planks("I change the value to {string} and blur the input")
   * @planks("I change the value to {string} and press Escape")
   * @planks("I clear the edit input and press Enter")
   */
  function bindItemEvents() {
    // Toggle
    var toggles = todoList.querySelectorAll('.toggle');
    for (var i = 0; i < toggles.length; i++) {
      toggles[i].addEventListener('change', function () {
        var li = this.closest('li');
        if (!li) return;
        var id = li.getAttribute('data-id');
        store.toggle(id);
        render();
      });
    }

    // Destroy
    var destroys = todoList.querySelectorAll('.destroy');
    for (var i = 0; i < destroys.length; i++) {
      destroys[i].addEventListener('click', function () {
        var li = this.closest('li');
        if (!li) return;
        var id = li.getAttribute('data-id');
        store.remove(id);
        render();
      });
    }

    // Double-click to edit
    var labels = todoList.querySelectorAll('.view label');
    for (var i = 0; i < labels.length; i++) {
      labels[i].addEventListener('dblclick', function () {
        var li = this.closest('li');
        if (!li) return;
        li.classList.add('editing');
        var editInput = li.querySelector('.edit');
        editInput.focus();
        editInput.value = editInput.value;
      });
    }

    // Edit handlers
    var edits = todoList.querySelectorAll('.edit');
    for (var i = 0; i < edits.length; i++) {
      edits[i].addEventListener('keydown', function (e) {
        var li = this.closest('li');
        if (!li) return;
        var id = li.getAttribute('data-id');

        if (e.keyCode === ENTER_KEY) {
          var val = this.value.trim();
          if (val) {
            store.update(id, { title: val });
          } else {
            store.remove(id);
          }
          li.classList.remove('editing');
          render();
        } else if (e.keyCode === ESCAPE_KEY) {
          var original = store.get(id);
          this.value = original ? original.title : '';
          li.classList.remove('editing');
        }
      });

      edits[i].addEventListener('blur', function () {
        var li = this.closest('li');
        if (!li) return;
        if (!li.classList.contains('editing')) return;
        var id = li.getAttribute('data-id');
        var val = this.value.trim();
        if (val) {
          store.update(id, { title: val });
        } else {
          store.remove(id);
        }
        li.classList.remove('editing');
        render();
      });
    }
  }

  // -----------------------------------------------------------------------
  // Global events
  // -----------------------------------------------------------------------

  newTodo.addEventListener('keydown', function (e) {
    if (e.keyCode === ENTER_KEY) {
      var val = this.value.trim();
      if (val) {
        store.add(val);
        this.value = '';
        render();
      }
    }
  });

  toggleAll.addEventListener('change', function () {
    store.toggleAll(this.checked);
    render();
  });

  clearCompleted.addEventListener('click', function () {
    store.clearCompleted();
    render();
  });

  window.addEventListener('hashchange', function () {
    render();
  });

  bindFilterNav();

  // -----------------------------------------------------------------------
  // Bootstrap
  // -----------------------------------------------------------------------

  render();
})();

