diff --git a/features/support/step_definitions.js b/features/support/step_definitions.js
index d87c27e..775fe88 100644
--- a/features/support/step_definitions.js
+++ b/features/support/step_definitions.js
@@ -421,6 +421,69 @@ When('I reload the app', function () {
 // Schema conformance
 // ---------------------------------------------------------------------------

+// ---------------------------------------------------------------------------
+// Plank storage: save element references for DOM-persistence checks
+// ---------------------------------------------------------------------------
+
+var savedElements = {};
+var savedAllElements = [];
+
+When('I save the element reference for {string}', function (text) {
+  const li = findTodoItem(this.document, text);
+  assert.ok(li, `expected todo "${text}" to exist`);
+  savedElements[text] = li;
+});
+
+When('I save all todo element references', function () {
+  const items = todoItems.call(this);
+  assert.ok(items.length > 0, 'expected at least one todo');
+  savedAllElements = Array.from(items);
+});
+
+Then('the saved element for {string} should have class {string}', function (text, cls) {
+  const el = savedElements[text];
+  assert.ok(el, `expected saved element for "${text}"`);
+  assert.ok(el.classList.contains(cls),
+    `expected saved element for "${text}" to have class "${cls}"`);
+});
+
+Then('the saved element should be attached to the document', function () {
+  // Check the most recently singular saved element
+  const keys = Object.keys(savedElements);
+  assert.ok(keys.length > 0, 'expected at least one saved element');
+  const el = savedElements[keys[keys.length - 1]];
+  assert.ok(el, 'expected a saved element');
+  assert.ok(el.ownerDocument && el.ownerDocument.contains(el),
+    'expected saved element to be attached to the document');
+});
+
+Then('each saved element should have class {string}', function (cls) {
+  assert.ok(savedAllElements.length > 0, 'expected saved elements');
+  for (let i = 0; i < savedAllElements.length; i++) {
+    assert.ok(savedAllElements[i].classList.contains(cls),
+      `expected saved element ${i} to have class "${cls}"`);
+  }
+});
+
+Then('each saved element should be attached to the document', function () {
+  assert.ok(savedAllElements.length > 0, 'expected saved elements');
+  for (let i = 0; i < savedAllElements.length; i++) {
+    assert.ok(savedAllElements[i].ownerDocument && savedAllElements[i].ownerDocument.contains(savedAllElements[i]),
+      `expected saved element ${i} to be attached to the document`);
+  }
+});
+
+Then('the saved element for {string} should be attached to the document', function (text) {
+  const el = savedElements[text];
+  assert.ok(el, `expected saved element for "${text}"`);
+  assert.ok(el.ownerDocument && el.ownerDocument.contains(el),
+    `expected saved element for "${text}" to be attached to the document`);
+});
+
+// ---------------------------------------------------------------------------
+// Schema conformance
+// ---------------------------------------------------------------------------
+
 Then('the localStorage todo items conform to the {string} schema in {string}', function (schemaId, schemaPath) {
   const schemaFile = path.resolve(ROOT, schemaPath);
   assert.ok(fs.existsSync(schemaFile), `schema file not found: ${schemaPath}`);
